1	import { emit, listen } from "@tauri-apps/api/event";
2	import { Send } from "lucide-solid";
3	import { For, Show, createSignal, onCleanup, onMount } from "solid-js";
4	import { useI18n } from "../../../i18n";
5	import { useSettings } from "../../../lib/settingsStore";
6	
7	interface LearningStepProps {
8		onTranscriptionComplete: () => void;
9	}
10	
11	function parseHotkeyParts(hotkey: string): string[] {
12		const DISPLAY_MAP: Record<string, string> = {
13			Command: "\u2318",
14			Control: "\u2303",
15			Alt: "\u2325",
16			Shift: "\u21E7",
17			LeftControl: "Left \u2303",
18			RightControl: "Right \u2303",
19			LeftOption: "Left \u2325",
20			RightOption: "Right \u2325",
21			LeftCommand: "Left \u2318",
22			RightCommand: "Right \u2318",
23			Space: "Space",
24		};
25		return hotkey.split("+").map((part) => DISPLAY_MAP[part] ?? part);
26	}
27	
28	export default function LearningStep(props: LearningStepProps) {
29		const [t] = useI18n();
30		const settings = useSettings();
31		const [messages, setMessages] = createSignal<string[]>([]);
32		const [inputText, setInputText] = createSignal("");
33	
34		let inputRef: HTMLInputElement | undefined;
35	
36		const hotkeyParts = () => parseHotkeyParts(settings().hotkey);
37		const holdToSpeakHotkeyParts = () => parseHotkeyParts(settings().holdToSpeakHotkey);
38	
39		const addMessage = () => {
40			const text = inputText().trim();
41			if (!text) return;
42			setMessages((prev) => [...prev, text]);
43			setInputText("");
44			props.onTranscriptionComplete();
45		};
46	
47		onMount(async () => {
48			// biome-ignore lint/style/useConst: cleanup needs the listener reference before async setup finishes.
49			let unlisten: (() => void) | undefined;
50	
51			onCleanup(() => {
52				unlisten?.();
53				emit("learning-step-active", false);
54			});
55	
56			await emit("learning-step-active", true);
57	
58			unlisten = await listen("transcription-created", () => {
59				// Small delay to ensure type_text has fully populated the input
60				setTimeout(() => {
61					addMessage();
62					inputRef?.focus();
63				}, 100);
64			});
65	
66			inputRef?.focus();
67		});
68	
69		return (
70			<div class="w-full max-w-4xl mx-auto">
71				{/* Terminal-style header */}
72				<div class="font-mono text-ac text-sm mb-8 tracking-wider text-center">
73					[STEP_06] &gt; TRY_IT_OUT
74				</div>
75	
76				<h2 class="font-mono text-xl uppercase tracking-wider text-txt-primary mb-2 text-center">
77					{t("onboarding.learningTitle")}
78				</h2>
79				<p class="font-mono text-sm text-txt-secondary mb-8 text-center">
80					{t("onboarding.learningDescription")}
81				</p>
82	
83				{/* Split view */}
84				<div class="flex gap-6">
85					{/* Left: Manual */}
86					<div class="flex-1 border border-border bg-th-surface p-6">
87						<div class="space-y-6">
88							{/* Step 1 */}
