1	import { useNavigate } from "@solidjs/router";
2	import { getVersion } from "@tauri-apps/api/app";
3	import { listen } from "@tauri-apps/api/event";
4	import { Result } from "better-result";
5	import { type ParentProps, Show, createSignal, onCleanup, onMount } from "solid-js";
6	import appIcon from "../src-tauri/icons/icon.svg";
7	import Sidebar from "./components/Navigation";
8	import SettingsModal from "./components/SettingsModal";
9	import OnboardingWizard from "./components/onboarding/OnboardingWizard";
10	import { listInstalledApps } from "./lib/commands/apps";
11	import { listSiteDictionaries } from "./lib/commands/dictionary";
12	import { checkModelStatus } from "./lib/commands/model";
13	import { errorFields, logDiagnostic } from "./lib/diagnostics";
14	import { preloadFavicons } from "./lib/favicons";
15	import { MODEL_DOWNLOAD_STEP } from "./lib/onboarding";
16	import { capture } from "./lib/posthog";
17	import {
18		initSettings,
19		markOnboardingComplete,
20		resumeOnboardingAt,
21		updateMicrophone,
22		useSettings,
23	} from "./lib/settingsStore";
24	
25	const FORCE_SHOW_ONBOARDING =
26		import.meta.env.DEV && import.meta.env.VITE_FORCE_ONBOARDING === "true";
27	
28	type TauriWindow = Window & {
29		__TAURI_INTERNALS__?: unknown;
30	};
31	
32	function waitForTauriIPC(): Promise<void> {
33		if ((window as TauriWindow).__TAURI_INTERNALS__) return Promise.resolve();
34	
35		return new Promise((resolve, reject) => {
36			const timeout = setTimeout(() => {
37				clearInterval(interval);
38				reject(new Error("Tauri IPC bridge not ready after 5s"));
39			}, 5000);
40	
41			const interval = setInterval(() => {
42				if ((window as TauriWindow).__TAURI_INTERNALS__) {
43					clearInterval(interval);
44					clearTimeout(timeout);
45					resolve();
46				}
47			}, 50);
48		});
49	}
50	
51	function App(props: ParentProps) {
52		const settings = useSettings();
53		const navigate = useNavigate();
54		const [isSettingsOpen, setIsSettingsOpen] = createSignal(false);
55		const [isReady, setIsReady] = createSignal(false);
56	
57		const shouldShowOnboarding = () => {
58			if (FORCE_SHOW_ONBOARDING) return true;
59			return !settings().onboardingComplete;
60		};
61	
62		onMount(async () => {
63			const handleWindowError = (event: ErrorEvent) => {
64				logDiagnostic("error", "app", "window_error", {
65					message: event.message,
66					source: event.filename,
67					line: event.lineno,
68					column: event.colno,
69					error: errorFields(event.error),
70				});
71			};
72			const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
73				logDiagnostic("error", "app", "unhandled_rejection", {
74					reason: errorFields(event.reason),
75				});
76			};
77			window.addEventListener("error", handleWindowError);
78			window.addEventListener("unhandledrejection", handleUnhandledRejection);
79			onCleanup(() => {
80				window.removeEventListener("error", handleWindowError);
81				window.removeEventListener("unhandledrejection", handleUnhandledRejection);
82			});
83	
84			try {
85				logDiagnostic("info", "app", "mount_started");
86				capture("app_opened");
87				await waitForTauriIPC();
88	
89				const appVersion = await Result.tryPromise(() => getVersion());
90				logDiagnostic("info", "app", "ipc_ready", {
91					version: Result.isOk(appVersion) ? appVersion.value : null,
92				});
93	
94				await initSettings();
95				logDiagnostic("info", "app", "settings_initialized", {
96					onboardingComplete: settings().onboardingComplete,
97					onboardingStep: settings().onboardingStep,
98					defaultStyle: settings().defaultStyle,
99				});
100	
101				const modelReady = await checkModelStatus();
102				if (Result.isOk(modelReady) && !modelReady.value && settings().onboardingComplete) {
103					logDiagnostic("warn", "app", "model_missing_resume_onboarding");
104					await resumeOnboardingAt(MODEL_DOWNLOAD_STEP);
105				}
106				if (Result.isError(modelReady)) {
107					logDiagnostic("error", "app", "model_status_failed", errorFields(modelReady.error));
108					console.error("Failed to verify Whisper model state:", modelReady.error);
109				}
110	
111				setIsReady(true);
112				logDiagnostic("info", "app", "ready");
113	
114				void listSiteDictionaries().then((result) => {
115					if (Result.isOk(result)) {
116						logDiagnostic("debug", "app", "site_dictionaries_loaded", {
117							count: result.value.length,
118						});
119						preloadFavicons(result.value.map((g) => g.domain));
120					} else {
121						logDiagnostic("error", "app", "site_dictionaries_failed", errorFields(result.error));
122					}
123				});
124	
125				void listInstalledApps().then((result) => {
126					if (Result.isOk(result)) {
127						logDiagnostic("debug", "app", "installed_apps_loaded", {
128							count: result.value.length,
129						});
130					} else {
131						logDiagnostic("error", "app", "installed_apps_failed", errorFields(result.error));
132					}
133				});
134	
135				const unlistenNavigate = await listen<string>("navigate", (event) => {
136					logDiagnostic("debug", "app", "navigate_event", { path: event.payload });
137					navigate(event.payload);
138				});
139				onCleanup(() => unlistenNavigate());
140	
141				const unlistenMicrophone = await listen<string>("select-microphone", async (event) => {
142					const deviceName = event.payload;
143					logDiagnostic("debug", "app", "select_microphone_event", {
144						hasDeviceName: Boolean(deviceName),
145					});
146					await updateMicrophone(deviceName || null);
147				});
148				onCleanup(() => unlistenMicrophone());
149	
150				const unlistenAccessibility = await listen("accessibility-permission-needed", () => {
151					logDiagnostic("warn", "app", "accessibility_permission_needed");
152					setIsSettingsOpen(true);
153				});
154				onCleanup(() => unlistenAccessibility());
155	
156				const handleKeyDown = (e: KeyboardEvent) => {
157					if (e.metaKey && e.key === ",") {
158						e.preventDefault();
159						logDiagnostic("debug", "app", "settings_shortcut_pressed");
160						setIsSettingsOpen(true);
161					}
162				};
163				window.addEventListener("keydown", handleKeyDown);
164				onCleanup(() => window.removeEventListener("keydown", handleKeyDown));
165			} catch (error) {
166				logDiagnostic("error", "app", "mount_failed", errorFields(error));
167				throw error;
168			}
169		});
170	
171		return (
172			<div class="relative min-h-screen h-full w-full bg-th-base transition-colors">
173				<div
174					class="pointer-events-none absolute inset-0 z-0"
175					style={{
176						"background-image":
177							"linear-gradient(var(--color-grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--color-grid-line) 1px, transparent 1px)",
178						"background-size": "40px 40px",
179					}}
180				/>
181				<div class="absolute top-0 left-0 right-0 h-6 z-50" data-tauri-drag-region />
182				<Show when={!isReady()}>
183					<div class="h-full flex flex-col items-center justify-center">
184						<img src={appIcon} alt="VoxFusion" class="w-16 h-16 mb-8" />
185						<div class="w-48 h-1 bg-border overflow-hidden">
186							<div class="w-1/4 h-full bg-ac animate-slide" />
187						</div>
188					</div>
189				</Show>
190				<Show when={isReady()}>
191					<Show
192						when={!shouldShowOnboarding()}
193						fallback={
194							<OnboardingWizard
195								initialStep={settings().onboardingStep}
196								onComplete={() => {
197									capture("onboarding_completed");
198									markOnboardingComplete();
199								}}
200							/>
201						}
202					>
203						<div class="flex h-full">
204							<Sidebar onOpenSettings={() => setIsSettingsOpen(true)} />
205							<main class="flex-1 overflow-auto pt-6">{props.children}</main>
206						</div>
207						<SettingsModal isOpen={isSettingsOpen()} onClose={() => setIsSettingsOpen(false)} />
208					</Show>
209				</Show>
210			</div>
211		);
212	}
213	
214	export default App;
