1	import { listen } from "@tauri-apps/api/event";
2	import { Result } from "better-result";
3	import { AlertCircle, Check, Download, Loader } from "lucide-solid";
4	import { For, Show, createSignal, onCleanup, onMount } from "solid-js";
5	import type { I18nContextType } from "../../i18n";
6	import {
7		type ModelDownloadProgress,
8		type ModelInfo,
9		downloadModel,
10		listModels,
11		setActiveModel,
12	} from "../../lib/commands/model";
13	import { capture } from "../../lib/posthog";
14	
15	interface ModelSettingsProps {
16		t: I18nContextType[0];
17	}
18	
19	export default function ModelSettings(props: ModelSettingsProps) {
20		const [models, setModels] = createSignal<ModelInfo[]>([]);
21		const [progress, setProgress] = createSignal<Record<string, number>>({});
22		const [downloadingId, setDownloadingId] = createSignal<string | null>(null);
23		const [busyId, setBusyId] = createSignal<string | null>(null);
24		const [error, setError] = createSignal<string | null>(null);
25	
26		const refresh = async () => {
27			const result = await listModels();
28			if (Result.isOk(result)) {
29				setModels(result.value);
30			} else {
31				setError(result.error.message);
32			}
33		};
34	
35		onMount(async () => {
36			await refresh();
37	
38			const unlisten = await listen<ModelDownloadProgress>("model-download-progress", (event) => {
39				setProgress((prev) => ({ ...prev, [event.payload.model_id]: event.payload.progress }));
40				if (event.payload.progress >= 100) {
41					setDownloadingId((current) => (current === event.payload.model_id ? null : current));
42					void refresh();
43				}
44			});
45			onCleanup(() => unlisten());
46		});
47	
48		const handleDownload = async (model: ModelInfo) => {
49			setError(null);
50			setDownloadingId(model.id);
51			setProgress((prev) => ({ ...prev, [model.id]: 0 }));
52			capture("settings_model_download_started", { model: model.id });
53	
54			const result = await downloadModel(model.id);
55			setDownloadingId(null);
56			if (Result.isError(result)) {
57				setError(result.error.message);
58			}
59			await refresh();
60		};
61	
62		const handleUse = async (model: ModelInfo) => {
63			setError(null);
64			setBusyId(model.id);
65			const result = await setActiveModel(model.id);
66			setBusyId(null);
67			if (Result.isError(result)) {
68				setError(result.error.message);
69				return;
70			}
71			capture("settings_model_changed", { model: model.id });
72			await refresh();
73		};
74	
75		return (
76			<div class="space-y-6">
77				<p class="font-mono text-xs text-txt-faint">{props.t("settings.modelsDescription")}</p>
78	
79				<div class="space-y-3">
80					<For each={models()}>
81						{(model) => (
82							<div
83								class={`border p-4 ${
84									model.active ? "border-ac bg-ac-bg" : "border-border-strong bg-th-surface"
85								}`}
86							>
87								<div class="flex items-start justify-between gap-3">
88									<div class="min-w-0">
89										<div class="flex items-center gap-2 flex-wrap">
90											<span class="font-mono text-sm text-txt-primary uppercase tracking-wider truncate">
91												{model.name}
92											</span>
93											<Show when={model.recommended}>
94												<span class="font-mono text-[10px] uppercase tracking-wider text-ac border border-ac px-1.5 py-0.5">
95													{props.t("settings.modelRecommended")}
96												</span>
97											</Show>
98											<Show when={model.experimental}>
99												<span class="font-mono text-[10px] uppercase tracking-wider text-txt-muted border border-border-strong px-1.5 py-0.5">
100													{props.t("settings.modelExperimental")}
101												</span>
102											</Show>
103										</div>
104										<div class="mt-1.5 font-mono text-xs text-txt-faint">
105											{model.size_label} · {model.languages}
106										</div>
107									</div>
108	
109									<div class="shrink-0">
110										<Show when={model.active}>
111											<div class="flex items-center gap-1.5 font-mono text-xs text-success uppercase tracking-wider">
112												<Check class="w-4 h-4" />
113												{props.t("settings.modelInUse")}
114											</div>
115										</Show>
116	
117										<Show when={!model.active && downloadingId() !== model.id}>
118											<Show
119												when={model.downloaded}
120												fallback={
121													<button
122														type="button"
123														onClick={() => handleDownload(model)}
124														class="flex items-center gap-1.5 px-3 py-1.5 bg-ac text-ac-on font-mono text-xs uppercase tracking-wider hover:bg-ac-hover transition-colors"
125													>
126														<Download class="w-3.5 h-3.5" />
127														{props.t("settings.modelDownload")}
128													</button>
129												}
130											>
131												<Show
132													when={!model.experimental}
133													fallback={
134														<div class="flex items-center gap-1.5 font-mono text-xs text-txt-muted uppercase tracking-wider">
135															<Check class="w-3.5 h-3.5 text-success" />
136															{props.t("settings.modelDownloaded")}
137														</div>
138													}
139												>
140													<button
141														type="button"
142														onClick={() => handleUse(model)}
143														disabled={busyId() === model.id}
144														class="px-3 py-1.5 border border-ac text-ac font-mono text-xs uppercase tracking-wider hover:bg-ac hover:text-ac-on transition-colors disabled:opacity-50"
145													>
146														{props.t("settings.modelUse")}
147													</button>
148												</Show>
149											</Show>
150										</Show>
151									</div>
152								</div>
153	
154								<Show when={downloadingId() === model.id}>
155									<div class="mt-3 space-y-2">
156										<div class="w-full h-2 bg-border overflow-hidden">
157											<div
158												class="h-full bg-ac transition-all duration-300"
159												style={{ width: `${progress()[model.id] ?? 0}%` }}
160											/>
