2	import { Check, Copy } from "lucide-solid";
3	import { Show, createSignal } from "solid-js";
4	import { useI18n } from "../i18n";
5	import { capture } from "../lib/posthog";
6	
7	type Transcription = {
8		id: string;
9		text: string;
10		processing_time_ms: number;
11		audio_duration_ms: number | null;
12		created_at: string;
13	};
14	
15	type Props = {
16		transcription: Transcription;
17	};
18	
19	export default function TranscriptionCard(props: Props) {
20		const [t, { locale }] = useI18n();
21		const [copied, setCopied] = createSignal(false);
22		const [isHovered, setIsHovered] = createSignal(false);
23	
24		const handleCopy = async () => {
25			await writeText(props.transcription.text);
26			capture("transcription_copied", {
27				transcription_id: props.transcription.id,
28				text_length: props.transcription.text.length,
29			});
30			setCopied(true);
31			setTimeout(() => setCopied(false), 2000);
32		};
33	
34		const formatProcessingTime = (ms: number) => {
35			return ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`;
36		};
37	
38		const formatTime = (dateStr: string) => {
39			const date = new Date(dateStr);
40			return date.toLocaleTimeString(locale(), {
41				hour: "2-digit",
42				minute: "2-digit",
43			});
44		};
45	
46		const truncateText = (text: string, maxLength = 150) => {
47			if (text.length <= maxLength) return text;
48			return `${text.slice(0, maxLength)}...`;
49		};
50	
51		return (
52			<div
53				class="group relative p-3 hover:bg-th-hover"
54				onMouseEnter={() => setIsHovered(true)}
55				onMouseLeave={() => setIsHovered(false)}
56			>
57				<p class="text-txt-primary font-mono text-sm leading-relaxed mb-2">
