import { writeText } from "@tauri-apps/plugin-clipboard-manager";
import { Check, Copy } from "lucide-solid";
import { Show, createSignal } from "solid-js";
import { useI18n } from "../i18n";
import { capture } from "../lib/posthog";

type Transcription = {
	id: string;
	text: string;
	processing_time_ms: number;
	audio_duration_ms: number | null;
	created_at: string;
};

type Props = {
	transcription: Transcription;
};

export default function TranscriptionCard(props: Props) {
	const [t, { locale }] = useI18n();
	const [copied, setCopied] = createSignal(false);
	const [isHovered, setIsHovered] = createSignal(false);

	const handleCopy = async () => {
		await writeText(props.transcription.text);
		capture("transcription_copied", {
			transcription_id: props.transcription.id,
			text_length: props.transcription.text.length,
		});
		setCopied(true);
		setTimeout(() => setCopied(false), 2000);
	};

	const formatProcessingTime = (ms: number) => {
		return ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`;
	};

	const formatTime = (dateStr: string) => {
		const date = new Date(dateStr);
		return date.toLocaleTimeString(locale(), {
			hour: "2-digit",
			minute: "2-digit",
		});
	};

	const truncateText = (text: string, maxLength = 150) => {
		if (text.length <= maxLength) return text;
		return `${text.slice(0, maxLength)}...`;
	};

	return (
		<div
			class="group relative p-3 hover:bg-th-hover"
			onMouseEnter={() => setIsHovered(true)}
			onMouseLeave={() => setIsHovered(false)}
		>
			<p class="text-txt-primary font-mono text-sm leading-relaxed mb-2">
				{truncateText(props.transcription.text)}
			</p>

			<div class="flex items-center gap-3 text-txt-muted font-mono text-xs">
				<span>{formatTime(props.transcription.created_at)}</span>
				<span>{formatProcessingTime(props.transcription.processing_time_ms)}</span>
			</div>

			<Show when={isHovered() || copied()}>
				<button
					type="button"
					onClick={handleCopy}
					class="absolute top-2 right-2 p-1.5 bg-th-base border border-border-strong hover:border-ac text-txt-secondary transition-colors"
					title={copied() ? t("transcription.copied") : t("transcription.copy")}
				>
					<Show when={copied()} fallback={<Copy class="w-3.5 h-3.5" />}>
						<Check class="w-3.5 h-3.5 text-success" />
					</Show>
				</button>
			</Show>
		</div>
	);
}

import { A, useLocation } from "@solidjs/router";
import { BookOpen, Home, Settings, Wand2 } from "lucide-solid";
import { useI18n } from "../i18n";
import UpdateNotification from "./UpdateNotification";

interface SidebarProps {
	onOpenSettings: () => void;
}

export default function Sidebar(props: SidebarProps) {
	const [t] = useI18n();
	const location = useLocation();

	const isActive = (path: string) =>
		path === "/"
			? location.pathname === path
			: location.pathname === path || location.pathname.startsWith(`${path}/`);

	return (
		<aside class="w-56 bg-th-base border-r border-border flex flex-col h-full">
			<nav class="flex-1 p-3 pt-9 space-y-1">
				<A
					href="/"
					class={`flex items-center gap-3 px-3 py-2 font-mono uppercase tracking-wider text-xs transition-colors ${
						isActive("/")
							? "text-ac border-l-2 border-ac bg-th-surface"
							: "text-txt-secondary hover:text-txt-primary hover:bg-th-surface border-l-2 border-transparent"
					}`}
				>
					<Home class="w-4 h-4" />
					<span>01 {t("sidebar.home")}</span>
				</A>
				<A
					href="/dictionary"
					class={`flex items-center gap-3 px-3 py-2 font-mono uppercase tracking-wider text-xs transition-colors ${
						isActive("/dictionary")
							? "text-ac border-l-2 border-ac bg-th-surface"
							: "text-txt-secondary hover:text-txt-primary hover:bg-th-surface border-l-2 border-transparent"
					}`}
				>
					<BookOpen class="w-4 h-4" />
					<span>02 {t("sidebar.dictionary")}</span>
				</A>
				<A
					href="/style"
					class={`flex items-center gap-3 px-3 py-2 font-mono uppercase tracking-wider text-xs transition-colors ${
						isActive("/style")
							? "text-ac border-l-2 border-ac bg-th-surface"
							: "text-txt-secondary hover:text-txt-primary hover:bg-th-surface border-l-2 border-transparent"
					}`}
				>
					<Wand2 class="w-4 h-4" />
					<span>03 {t("sidebar.style")}</span>
				</A>
			</nav>

			<UpdateNotification />

			<div class="p-3 border-t border-border">
				<button
					type="button"
					onClick={() => props.onOpenSettings()}
					class="flex items-center gap-3 w-full px-3 py-2 font-mono uppercase tracking-wider text-xs text-txt-secondary hover:text-txt-primary hover:bg-th-surface transition-colors"
				>
					<Settings class="w-4 h-4 text-txt-secondary" />
					<span>{t("sidebar.settings")}</span>
				</button>
			</div>
		</aside>
	);
}

