525			<Show
526				when={props.src}
527				fallback={
528					<div class="w-8 h-8 shrink-0 bg-th-input border border-border flex items-center justify-center text-txt-muted font-mono text-xs">
529						{props.alt.charAt(0).toUpperCase()}
