1	use futures_util::StreamExt;
2	use std::fs;
3	use std::path::PathBuf;
4	use std::sync::Mutex;
5	use tauri::{Emitter, Manager};
6	
7	/// Speech-to-text engine that backs a model. Each engine has its own
8	/// inference path in [`crate::handlers::whisper::transcribe_audio`].
9	#[derive(Clone, Copy, PartialEq, Eq)]
10	pub enum Engine {
11	    Whisper,
12	    Parakeet,
13	}
14	
15	impl Engine {
16	    pub fn as_str(self) -> &'static str {
17	        match self {
18	            Engine::Whisper => "whisper",
19	            Engine::Parakeet => "parakeet",
20	        }
21	    }
22	}
23	
24	/// Static metadata describing a downloadable transcription model.
25	pub struct ModelInfo {
26	    /// Stable identifier used by the frontend and persisted as the active model.
27	    pub id: &'static str,
28	    pub name: &'static str,
29	    pub engine: Engine,
30	    /// Local filename inside the models directory.
31	    pub filename: &'static str,
32	    /// Direct (single-file) download URL.
33	    pub url: &'static str,
34	    /// Exact size in bytes when known; used for download validation and as a
35	    /// progress fallback when the server omits `Content-Length`.
36	    pub expected_size: Option<u64>,
37	    pub size_label: &'static str,
38	    pub languages: &'static str,
39	    /// Marks a model whose engine cannot transcribe yet. Such a model can be
40	    /// downloaded but cannot be made the active transcription model.
41	    pub experimental: bool,
42	    pub recommended: bool,
43	}
44	
45	pub const DEFAULT_MODEL_ID: &str = "whisper-large-v3-turbo";
46	
47	/// The model registry — the single source of truth for available models.
48	const MODELS: &[ModelInfo] = &[
49	    ModelInfo {
50	        id: "whisper-large-v3-turbo",
51	        name: "Whisper Large v3 Turbo",
52	        engine: Engine::Whisper,
53	        filename: "ggml-large-v3-turbo.bin",
54	        url: "https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-large-v3-turbo.bin",
55	        expected_size: Some(1_624_555_275),
56	        size_label: "~1.5 GB",
57	        languages: "99 languages",
58	        experimental: false,
59	        recommended: true,
60	    },
61	    ModelInfo {
62	        id: "parakeet-tdt-0.6b-v3",
63	        name: "Parakeet TDT 0.6B v3",
64	        engine: Engine::Parakeet,
65	        filename: "parakeet-tdt-0.6b-v3-q8_0.gguf",
66	        // GGUF port of NVIDIA's Parakeet TDT 0.6B v3 (q8_0), run via the crispasr
67	        // engine (see handlers::parakeet).
68	        url: "https://huggingface.co/cstr/parakeet-tdt-0.6b-v3-GGUF/resolve/main/parakeet-tdt-0.6b-v3-q8_0.gguf",
69	        expected_size: Some(745_121_600),
70	        size_label: "~745 MB",
71	        languages: "25 European languages",
72	        experimental: false,
73	        recommended: false,
74	    },
75	];
76	
77	pub fn all_models() -> &'static [ModelInfo] {
78	    MODELS
79	}
80	
81	pub fn find_model(id: &str) -> Option<&'static ModelInfo> {
82	    MODELS.iter().find(|model| model.id == id)
83	}
84	
85	pub fn get_models_dir(app_handle: &tauri::AppHandle) -> Result<PathBuf, String> {
86	    let data_dir = app_handle.path().app_data_dir().map_err(|e| e.to_string())?;
87	    let model_dir = data_dir.join("models");
88	    fs::create_dir_all(&model_dir).map_err(|e| e.to_string())?;
89	    Ok(model_dir)
90	}
91	
92	pub fn model_path(app_handle: &tauri::AppHandle, model: &ModelInfo) -> Result<PathBuf, String> {
93	    Ok(get_models_dir(app_handle)?.join(model.filename))
94	}
95	
96	/// Whether the model's file exists on disk and matches its expected size
97	/// (when known). Models without a known size are considered present when the
98	/// file is non-empty.
99	pub fn is_downloaded(app_handle: &tauri::AppHandle, model: &ModelInfo) -> bool {
100	    let Ok(path) = model_path(app_handle, model) else {
101	        return false;
102	    };
103	    match fs::metadata(&path) {
104	        Ok(meta) => match model.expected_size {
105	            Some(size) => meta.len() == size,
106	            None => meta.len() > 0,
107	        },
108	        Err(_) => false,
109	    }
110	}
111	
112	// ---------------------------------------------------------------------------
113	// Active model selection
114	// ---------------------------------------------------------------------------
115	
116	/// The transcription model currently in use. Mirrored to `<models>/active-model.txt`
117	/// so the choice survives restarts and is readable from the transcription path.
118	pub struct ActiveModel(pub Mutex<String>);
119	
120	fn active_model_file(app_handle: &tauri::AppHandle) -> Result<PathBuf, String> {
121	    Ok(get_models_dir(app_handle)?.join("active-model.txt"))
122	}
123	
124	/// Reads the persisted active model id, falling back to the default when it is
125	/// missing or no longer a known model.
126	fn load_active_model_id(app_handle: &tauri::AppHandle) -> String {
127	    active_model_file(app_handle)
128	        .ok()
129	        .and_then(|path| fs::read_to_string(path).ok())
130	        .map(|raw| raw.trim().to_string())
131	        .filter(|id| find_model(id).is_some())
132	        .unwrap_or_else(|| DEFAULT_MODEL_ID.to_string())
133	}
134	
135	/// Builds the managed [`ActiveModel`] state during app setup.
136	pub fn init_active_model(app_handle: &tauri::AppHandle) -> ActiveModel {
137	    ActiveModel(Mutex::new(load_active_model_id(app_handle)))
138	}
139	
140	/// The active model id, defensively falling back to the default if the lock is
141	/// poisoned.
142	pub fn active_model_id(state: &tauri::State<'_, ActiveModel>) -> String {
143	    state
144	        .0
145	        .lock()
146	        .map(|guard| guard.clone())
147	        .unwrap_or_else(|_| DEFAULT_MODEL_ID.to_string())
148	}
149	
150	// ---------------------------------------------------------------------------
151	// Download
152	// ---------------------------------------------------------------------------
153	
154	#[derive(Clone, serde::Serialize)]
155	struct DownloadProgress {
156	    model_id: String,
157	    progress: u32,
158	}
159	
160	fn emit_progress(app_handle: &tauri::AppHandle, model_id: &str, progress: u32) {
161	    let _ = app_handle.emit(
162	        "model-download-progress",
163	        DownloadProgress {
164	            model_id: model_id.to_string(),
165	            progress,
166	        },
167	    );
168	}
169	
170	/// Streams a model's file to disk, emitting `model-download-progress` events
171	/// (`{ model_id, progress }`). The download is written to a temp file and
172	/// atomically renamed into place once validated.
173	pub async fn download_model_file(
174	    app_handle: &tauri::AppHandle,
175	    model: &ModelInfo,
176	) -> Result<(), String> {
177	    let destination = model_path(app_handle, model)?;
178	
179	    if is_downloaded(app_handle, model) {
180	        emit_progress(app_handle, model.id, 100);
181	        return Ok(());
182	    }
183	    // Drop any partial/mismatched previous attempt.
184	    if destination.exists() {
185	        let _ = fs::remove_file(&destination);
186	    }
187	
188	    let temp_path = destination.with_extension("download.tmp");
189	    let _ = fs::remove_file(&temp_path);
190	
191	    let client = reqwest::Client::builder()
192	        .timeout(std::time::Duration::from_secs(60 * 60))
193	        .build()
194	        .map_err(|e| format!("Failed to build HTTP client: {}", e))?;
195	    let response = client
196	        .get(model.url)
197	        .send()
198	        .await
199	        .map_err(|e| format!("Failed to start download: {}", e))?;
200	
201	    if !response.status().is_success() {
202	        return Err(format!("Download failed: HTTP {}", response.status()));
203	    }
204	
205	    let total_size = response
206	        .content_length()
207	        .or(model.expected_size)
208	        .unwrap_or(0);
209	
210	    let mut file =
211	        fs::File::create(&temp_path).map_err(|e| format!("Failed to create file: {}", e))?;
212	
213	    let mut stream = response.bytes_stream();
214	    let mut downloaded: u64 = 0;
215	
216	    while let Some(chunk) = stream.next().await {
217	        let chunk = chunk.map_err(|e| {
218	            let _ = fs::remove_file(&temp_path);
219	            format!("Download failed: {}", e)
220	        })?;
221	
222	        std::io::Write::write_all(&mut file, &chunk).map_err(|e| {
223	            let _ = fs::remove_file(&temp_path);
224	            format!("Write failed: {}", e)
225	        })?;
226	
227	        downloaded += chunk.len() as u64;
228	
229	        let progress = if total_size > 0 {
230	            ((downloaded as f64 / total_size as f64) * 100.0).min(99.0) as u32
231	        } else {
232	            0
233	        };
234	        emit_progress(app_handle, model.id, progress);
235	    }
236	
237	    drop(file);
238	
239	    let actual_size = fs::metadata(&temp_path).map_err(|e| e.to_string())?.len();
240	    match model.expected_size {
241	        Some(expected) if actual_size != expected => {
242	            let _ = fs::remove_file(&temp_path);
243	            return Err(format!(
244	                "Download incomplete: got {} bytes, expected {}",
245	                actual_size, expected
246	            ));
247	        }
248	        None if actual_size == 0 => {
249	            let _ = fs::remove_file(&temp_path);
250	            return Err("Download incomplete: empty file".to_string());
251	        }
252	        _ => {}
253	    }
254	
255	    fs::rename(&temp_path, &destination).map_err(|e| {
256	        let _ = fs::remove_file(&temp_path);
257	        format!("Failed to finalize model: {}", e)
258	    })?;
259	
260	    emit_progress(app_handle, model.id, 100);
261	
262	    Ok(())
263	}
264	
265	// ---------------------------------------------------------------------------
266	// Commands
267	// ---------------------------------------------------------------------------
268	
269	/// Serializable view of a model for the frontend, including runtime state.
270	#[derive(serde::Serialize)]
271	pub struct ModelDto {
272	    pub id: String,
273	    pub name: String,
274	    pub engine: String,
275	    pub size_label: String,
276	    pub languages: String,
277	    pub experimental: bool,
278	    pub recommended: bool,
279	    pub downloaded: bool,
280	    pub active: bool,
281	}
282	
283	#[tauri::command]
284	pub async fn list_models(
285	    app_handle: tauri::AppHandle,
286	    active: tauri::State<'_, ActiveModel>,
287	) -> Result<Vec<ModelDto>, String> {
288	    let active_id = active_model_id(&active);
289	    Ok(all_models()
290	        .iter()
291	        .map(|model| ModelDto {
292	            id: model.id.to_string(),
293	            name: model.name.to_string(),
294	            engine: model.engine.as_str().to_string(),
295	            size_label: model.size_label.to_string(),
296	            languages: model.languages.to_string(),
297	            experimental: model.experimental,
298	            recommended: model.recommended,
299	            downloaded: is_downloaded(&app_handle, model),
300	            active: model.id == active_id,
301	        })
302	        .collect())
303	}
304	
305	#[tauri::command]
306	pub async fn get_active_model(active: tauri::State<'_, ActiveModel>) -> Result<String, String> {
307	    Ok(active_model_id(&active))
308	}
309	
310	#[tauri::command]
311	pub async fn set_active_model(
312	    app_handle: tauri::AppHandle,
313	    active: tauri::State<'_, ActiveModel>,
314	    model_id: String,
315	) -> Result<(), String> {
316	    let model = find_model(&model_id).ok_or_else(|| format!("Unknown model: {}", model_id))?;
317	
318	    if model.experimental {
319	        return Err(format!(
320	            "{} is experimental and not yet available for transcription.",
321	            model.name
322	        ));
323	    }
324	    if !is_downloaded(&app_handle, model) {
325	        return Err(format!("{} is not downloaded yet.", model.name));
326	    }
327	
328	    {
329	        let mut guard = active.0.lock().map_err(|e| e.to_string())?;
330	        *guard = model.id.to_string();
331	    }
332	
333	    let file = active_model_file(&app_handle)?;
334	    fs::write(&file, model.id)
335	        .map_err(|e| format!("Failed to persist model selection: {}", e))?;
336	
337	    let _ = app_handle.emit("active-model-changed", model.id);
338	    Ok(())
339	}
340	
341	#[tauri::command]
342	pub async fn check_model_downloaded(
343	    app_handle: tauri::AppHandle,
344	    model_id: String,
345	) -> Result<bool, String> {
346	    let model = find_model(&model_id).ok_or_else(|| format!("Unknown model: {}", model_id))?;
347	    Ok(is_downloaded(&app_handle, model))
348	}
349	
350	#[tauri::command]
351	pub async fn download_model(app_handle: tauri::AppHandle, model_id: String) -> Result<(), String> {
352	    let model = find_model(&model_id).ok_or_else(|| format!("Unknown model: {}", model_id))?;
353	    download_model_file(&app_handle, model).await
354	}
355

