330	    }
331	    if let Some(dict) = dictionary.map(|d| d.trim()).filter(|d| !d.is_empty()) {
332	        parts.push(format!("{}", dict));
333	    }
334	    if parts.is_empty() {
335	        None
336	    } else {
337	        Some(parts.join("\n\n"))
338	    }
