201	    // Extract resources while holding the lock, then release lock before dropping
202	    let (stream_to_drop, writer_to_finalize, save_path) = {
203	        let state = RECORDING_STATE.lock().map_err(|err| err.to_string())?;
204	        if !state.is_recording.load(Ordering::SeqCst) {
205	            return Err("No recording in progress.".to_string());
206	        }
207	        state.is_recording.store(false, Ordering::SeqCst);
208	
209	        // Take the stream
210	        let stream = state.stream.lock().map_err(|err| err.to_string())?.take();
211	
212	        // Take the writer
213	        let writer = state.writer.lock().map_err(|err| err.to_string())?.take();
214	
215	        // Clear app handle
216	        *state.app_handle.lock().map_err(|err| err.to_string())? = None;
217	
218	        // Get and clear the save path
219	        let save_path = state
220	            .save_path
221	            .lock()
222	            .map_err(|err| err.to_string())?
223	            .take()
224	            .ok_or("No recording in progress or save path not set.".to_string())?;
225	
226	        (stream, writer, save_path)
227	    };
228	    // Lock is now released
229	
230	    // Stop the stream - pause first, then drop to ensure macOS releases microphone
231	    if let Some(stream) = stream_to_drop {
232	        let _ = stream.0.pause();
233	        drop(stream.0);
234	    }
235	
236	    // Finalize the writer
237	    if let Some(writer) = writer_to_finalize {
238	        writer.finalize().map_err(|err| err.to_string())?;
239	    }
240	
241	    Ok(save_path)
242	}
