269	fn wav_spec_from_config(config: &cpal::SupportedStreamConfig) -> WavSpec {
270	    WavSpec {
271	        channels: config.channels() as _,
272	        sample_rate: config.sample_rate().0 as _,
273	        bits_per_sample: (config.sample_format().sample_size() * 8) as _,
274	        sample_format: sample_format(config.sample_format()),
275	    }
276	}
