278	// Timestamp tracking for throttling - using a static Instant for reference
279	static START_TIME: LazyLock<Instant> = LazyLock::new(Instant::now);
280	
281	fn write_input_data_with_levels<T, U>(
282	    input: &[T],
283	    writer: &WavWriterHandle,
284	    app_handle: &Arc<Mutex<Option<tauri::AppHandle>>>,
285	    last_emit_time: &Arc<AtomicU64>,
286	) where
287	    T: Sample,
288	    U: Sample + hound::Sample + FromSample<T>,
289	{
290	    if let Ok(mut guard) = writer.try_lock() {
291	        if let Some(writer) = guard.as_mut() {
292	            // Calculate RMS (root mean square) for audio level
293	            let mut sum: f64 = 0.0;
294	            let mut peak: f64 = 0.0;
295	
296	            for &sample in input.iter() {
297	                let sample_u: U = U::from_sample(sample);
298	                writer.write_sample(sample_u).ok();
299	
300	                // Convert to f32 first, then to f64 for level calculation
301	                let value: f32 = sample.to_float_sample().to_sample();
302	                let value_f64 = value as f64;
303	                sum += value_f64 * value_f64;
304	                peak = peak.max(value_f64.abs());
305	            }
306	
307	            // Calculate RMS and normalize to 0-100 range
308	            let rms = (sum / input.len() as f64).sqrt();
309	            // Use a combination of RMS and peak for more responsive visualization
310	            let level = ((rms * 0.7 + peak * 0.3) * 150.0).min(100.0);
311	
312	            // Throttle to ~30fps (every ~33ms)
313	            let now = START_TIME.elapsed().as_millis() as u64;
314	            let last = last_emit_time.load(Ordering::Relaxed);
315	            if now - last >= 33 {
316	                last_emit_time.store(now, Ordering::Relaxed);
317	
318	                // Emit to frontend
319	                if let Ok(handle_guard) = app_handle.try_lock() {
320	                    if let Some(h) = handle_guard.as_ref() {
321	                        let _ = h.emit("audio-level", level);
322	                    }
323	                }
324	            }
325	        }
326	    }
327	}
